import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const diaLifetimePhysicalScenarios={'soul-physical-ordinary':'a2-p15-r2c3','soul-physical-dedicated':'a2-p15-r2c3','heart-physical-ordinary':'a2-p15-r3c1','heart-physical-dedicated':'a2-p15-r3c1','soul-physical-ordinary-low':'a2-p15-r2c3','soul-physical-dedicated-low':'a2-p15-r2c3','heart-physical-ordinary-low':'a2-p15-r3c1','heart-physical-dedicated-low':'a2-p15-r3c1'} as const;
export type DiaLifetimePhysicalScenario=keyof typeof diaLifetimePhysicalScenarios;
export function isDiaLifetimePhysicalScenario(name:string):name is DiaLifetimePhysicalScenario{return Object.hasOwn(diaLifetimePhysicalScenarios,name);}
export function diaLifetimePhysicalMode(name:DiaLifetimePhysicalScenario){return {card:diaLifetimePhysicalScenarios[name],dedicated:name.includes('dedicated'),heart:name.startsWith('heart')};}
export function makeDiaLifetimePhysicalScenario(name:DiaLifetimePhysicalScenario,players:{id:string;name:string}[],options:{level?:number;owner?:string;follower?:'none'|'metal'|'guardian';targetStats?:number;deathAndRevival?:boolean}={}){
 if(name.endsWith('-low'))options={...options,targetStats:0};
 let s=createGame(players,entropy(),{startingSeat:3});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,options.owner??'魔聖母ディア');assignCharacter(s,b,'侍大将のシン');assignCharacter(s,c,'大神官ジル');assignCharacter(s,d,options.deathAndRevival?'魔導王ガイナス':'白魔術師シェリム');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};s.players[a]!.permanent!.magic_level=20+(options.level??7)-gameStats(s,a).magic_level;for(const id of [a,b,c])s.players[id]!.permanent!.spirit=20+(id===a?6:options.targetStats??6)-gameStats(s,id).spirit;if(options.targetStats!==undefined)for(const stat of ['warrior_level','magic_level'] as const)s.players[b]!.permanent![stat]=20+options.targetStats-gameStats(s,b)[stat];if(options.deathAndRevival)s.players[b]!.permanent!.endurance=100+4-gameStats(s,b).endurance;
 const card=takeCard(s,a,diaLifetimePhysicalScenarios[name]),advance=takeCard(s,a,'a2-p24-r1c2'),fire=takeCard(s,d,'a2-p15-r3c2'),fate=takeCard(s,d,'命運凶変'),teleport=takeCard(s,b,'a2-p06-r1c1'),evade=takeCard(s,b,'a2-p05-r3c1'),guard=options.follower==='none'?null:takeCard(s,b,options.follower==='guardian'?'守護者':'メタルゴーレム'),water=options.follower==='none'?null:takeCard(s,c,'水竜'),prayer=options.follower==='guardian'?takeCard(s,a,'必勝の祈り'):null,revive=options.deathAndRevival?takeCard(s,a,'a2-p13-r3c1'):null,ice=options.deathAndRevival?takeCard(s,d,'a2-p12-r2c2'):null;for(const id of [a,b,c,d])trimHand(s,id,card,advance,fire,fate,teleport,evade,...[guard,water,prayer,revive,ice].filter((x):x is string=>!!x));s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:Array(100).fill(1)},r=transition(s,input,e);if(!r.ok)throw Error(`DIA_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('DIA_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('DIA_IDS');}
 for(const id of [a,b,c,d]){if(id===b&&guard)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:guard});if(id===c&&water)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:water});act(id,{type:'PASS_SETUP'});}act(d,{type:'START_TURN'});act(d,{type:'CHOOSE_DRAW',draw:false});act(d,{type:'ATTACK',cardInstanceId:fire,targetIds:[a],dedicated:false});for(let n=0;n<300;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'});else if(s.phase==='action'&&id===a)break;else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>![card,advance,fate,prayer,revive,ice].includes(x)).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('DIA_PREP_PHASE');}if(s.players[a]!.damage!==5||s.phase!=='action'||s.seatOrder[s.turnSeat]!==a)throw Error('DIA_PREP_DAMAGE');return s;
}
